Extracting colors and blue cells, plus coordinate mapping.

```python
# python
from openpyxl import load_workbook
from openpyxl.utils import column_index_from_string

fp = '/Data2/v-weilinjin/workshop/AttributeBench/benchmarks/GAIA/2023/validation/65afbc8a-89ca-4ad5-8d62-355bb401f61d.xlsx'
wb = load_workbook(fp)
ws = wb.active

# Helper functions
def argb_to_rgb(argb):
    if not argb:
        return None
    return argb[-6:].upper()

def is_blue(hex_color):
    if not hex_color:
        return False
    r = int(hex_color[0:2], 16)
    g = int(hex_color[2:4], 16)
    b = int(hex_color[4:6], 16)
    return b > 200 and r < 80 and g < 200

def coord_to_indices(coord):
    # e.g., A1 -> (1,1)
    i = 0
    while i < len(coord) and not coord[i].isdigit():
        i += 1
    col = column_index_from_string(coord[:i])
    row = int(coord[i:])
    return (row, col)

map_data = {}
blue_cells = []
start_idx = None
end_idx = None

for row in ws.iter_rows():
    for cell in row:
        coord = cell.coordinate
        val = cell.value
        fill = cell.fill
        hex_color = None
        if fill and fill.fgColor and fill.fgColor.rgb:
            hex_color = argb_to_rgb(fill.fgColor.rgb)
        map_data[coord] = {'value': val, 'hex': hex_color}
        if is_blue(hex_color):
            blue_cells.append(coord)
        if val == 'START':
            start_idx = coord_to_indices(coord)
        if val == 'END':
            end_idx = coord_to_indices(coord)

print('Total cells:', len(map_data))
print('Blue cells:', len(blue_cells), 'Sample:', blue_cells[:8])
print('START idx:', start_idx, 'END idx:', end_idx)
print('Sample map_data:', list(map_data.items())[:10])
